EDITS = {'CHANGELOG.md': [('lines 1-1', '## [0.263.0] - the Delco Ave template, and a road grammar of one street\n', '## [0.264.0] - Bank Block and Warehouse Yard; a merged building\'s stairs skinned again\n\nThe walker: "my goal is to have like 8 of those templates with great diversity/dynamics", and "the stairs are only\nyellow as the default if they haven\'t been given a texture/skin, they should".\n\n### Added\n- **Two templates** (`packages/service/templates/`), toward eight: **Bank Block** -- the bank on a block with a\n  service lane behind (`road_grammar` `block`), afternoon; **Warehouse Yard** -- two warehouses on a yard by the\n  rail line (`surroundings` `yards`), midnight in the rain, high verticality. Each made and walked from the panel\'s\n  own brief (`design.brief_from_design`) with nobody touching anything: Bank Block seed 9003 PASS 90, three ladders\n  climbed; Warehouse Yard PASS 90, two ladders climbed; every shot station passed.\n- **Every template defaults to choices its own controls offer** (`tests/service/test_design.py`): the warehouse\'s\n  example brief says `night`, which no Time of day option is; its template says `midnight`.\n\n### Fixed\n- **A merged building\'s stairs are skinned, not Deli Counter\'s fallback yellow** (`merge_empties.SKIN_READS`,\n  `skin_keeps`). `drop_merged_modules` removed every kit module no file named, and a merged building (0.223.0) names\n  none, so `zoo_worldskin.gd`\'s stair pass -- which reads the first `floor_` module off `art/zoo/` -- found nothing,\n  and every stair in every merged building shipped yellow: on the bank\'s package of 2026-10-28, 0 `floor_` modules in\n  every building. The first module of each family the skin reads (`floor_`, `roof_`, `wall_` and its drywall\n  variant, `prop_`) is kept: a few small files a building, never instanced, no draw. MEASURED on bank_block_001 seed\n  9082 rebuilt, at the stations whose frames had shown it, by a yellow-pixel count first held to those frames: vault\n  0.57% -> 0.07%, lobby 0.98% -> 0.01%; the stairs read in the floor\'s concrete.\n\n### Tests\n- `tests/unit/test_skin_keeps.py` (new; fails on 0.263.0): the first module of each family the skin reads stays,\n  and the families are the skin\'s own; `tests/unit/test_merged_modules_dropped.py` follows it.\n\n## [0.263.0] - the Delco Ave template, and a road grammar of one street\n')], 'VERSION': [('lines 1-1', '0.263.0', '0.264.0')], 'packages/exporting/merge_empties.py': [('lines 173-174', '\ndef drop_merged_modules(export_dir: Path, report: dict) -> dict:\n', '\n#: THE MODULES THE RUNTIME SKIN READS BY FAMILY (0.264.0): `assets/godot/zoo_worldskin.gd` dresses a building\'s\n#: own geometry -- its stairs (`STAIR_FLIGHT_FAMILY`), slab reveals, vault ledges and ramps -- with the material of\n#: the FIRST module, in sort order, whose file name begins with a family prefix, read off `art/zoo/` at runtime. A\n#: merged building names no module, so this pass removed every one, and every stair in a merged building shipped in\n#: Deli Counter\'s fallback `gb_stair` yellow: measured on the bank\'s package of 2026-10-28, 0 `floor_` modules in\n#: every building and 100 stair meshes in bank_branch_a02\'s base, all yellow; the walker: "the stairs are only\n#: yellow as the default if they haven\'t been given a texture/skin". The first module of each family is kept --\n#: a few small files a building, never instanced, so no draw. (prefix, substring) as the skin\'s own rows; "" any.\nSKIN_READS = (("floor_", ""), ("roof_", ""), ("wall_", "_mdrywall"), ("wall_", ""), ("prop_", ""))\n\n\ndef skin_keeps(glbs) -> set:\n    """The file names `SKIN_READS` keeps from one building\'s sorted module list: for each row, the first name that\n    begins with its prefix and holds its substring."""\n    keep = set()\n    names = sorted(glbs)\n    for prefix, sub in SKIN_READS:\n        for name in names:\n            if name.startswith(prefix) and (not sub or sub in name):\n                keep.add(name)\n                break\n    return keep\n\n\ndef drop_merged_modules(export_dir: Path, report: dict) -> dict:\n'), ('lines 206-207', '        for glb in sorted((export_dir / lot / "art" / "zoo").glob("*.glb")):\n            if glb.name in named:\n', '        glbs = sorted((export_dir / lot / "art" / "zoo").glob("*.glb"))\n        skin = skin_keeps(g.name for g in glbs)\n        for glb in glbs:\n            if glb.name in named or glb.name in skin:\n')], 'tests/service/test_design.py': [('lines 154-154', '    assert [t["template_id"] for t in operations.list_templates({}, _NOOP)["templates"]] == ["delco_ave", T]\n', '    # Bank Block and Warehouse Yard (0.264.0): two more toward the walker\'s eight\n    assert [t["template_id"] for t in operations.list_templates({}, _NOOP)["templates"]] == [\n        "bank_block", "delco_ave", T, "warehouse_yard"]\n'), ('lines 165-165', '    assert labels["avenue"].startswith("One street") and not labels["T"].startswith("One street")\n', '    assert labels["avenue"].startswith("One street") and not labels["T"].startswith("One street")\n\n\ndef test_every_template_defaults_to_choices_its_own_controls_offer():\n    """0.264.0: the warehouse\'s example brief says `night`, which no Time of day option is; a template whose default\n    is not one of its own options opens the panel on a value the panel cannot show."""\n    for tid in design.templates():\n        for c in design.capabilities(tid):\n            if c["type"] == "choice":\n                assert c["default"] in [o["value"] for o in c["options"]], (tid, c["key"], c["default"])\n            elif c["type"] == "integer":\n                assert c["min"] <= c["default"] <= c["max"], (tid, c["key"], c["default"])\n')], 'tests/unit/test_merged_modules_dropped.py': [('lines 69-69', '    assert sorted(got["dropped"]) == ["lot/gs_a/art/zoo/wall_x.glb", "lot/gs_a/art/zoo/window_y.glb",\n', '    # 0.264.0: gs_a\'s `wall_x` is its first `wall_` module, which the runtime skin reads (`SKIN_READS`), so it\n    # stays; in gs_b the first is `wall_named_elsewhere`, and `wall_x` goes\n    assert sorted(got["dropped"]) == ["lot/gs_a/art/zoo/window_y.glb",\n'), ('lines 74-74', '    assert got["bytes"] == 4 * (400 + 50) + sum(\n', '    assert got["bytes"] == 3 * (400 + 50) + sum(\n'), ('lines 76-76', '    assert got["kept"] == 3\n', '    assert got["kept"] == 4                        # the three a file names, and gs_a\'s first wall module\n')]}
